2924436)","tree":{"sha":"c57a048553c74e2cc4dbc9aac77ae783da20c6ec","url":"https://api.github.com/repos/adriangmrraa/clinicforge/git/trees/c57a048553c74e2cc4dbc9aac77ae783da20c6ec"},"url":"https://api.github.com/repos/adriangmrraa/clinicforge/git/commits/f39c67fb087ddd4a05dae340d97c71acb954dba7","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/281972831?v=4","events_url":"https://api.github.com/users/CODEXY-ofi/events{/privacy}","followers_url":"https://api.github.com/users/CODEXY-ofi/followers","following_url":"https://api.github.com/users/CODEXY-ofi/following{/other_user}","gists_url":"https://api.github.com/users/CODEXY-ofi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/CODEXY-ofi","id":281972831,"login":"CODEXY-ofi","node_id":"U_kgDOEM6QXw","organizations_url":"https://api.github.com/users/CODEXY-ofi/orgs","received_events_url":"https://api.github.com/users/CODEXY-ofi/received_events","repos_url":"https://api.github.com/users/CODEXY-ofi/repos","site_admin":false,"starred_url":"https://api.github.com/users/CODEXY-ofi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/CODEXY-ofi/subscriptions","type":"User","url":"https://api.github.com/users/CODEXY-ofi","user_view_type":"public"},"html_url":"https://github.com/adriangmrraa/clinicforge/commit/f39c67fb087ddd4a05dae340d97c71acb954dba7","node_id":"C_kwDORRQYztoAKGYzOWM2N2ZiMDg3ZGRkNGEwNWRhZTM0MGQ5N2M3MWFjYjk1NGRiYTc","parents":[{"html_url":"https://github.com/adriangmrraa/clinicforge/commit/e6441db9dcb3891d1ed43514c2353687d7d705bb","sha":"e6441db9dcb3891d1ed43514c2353687d7d705bb","url":"https://api.github.com/repos/adriangmrraa/clinicforge/commits/e6441db9dcb3891d1ed43514c2353687d7d705bb"}],"sha":"f39c67fb087ddd4a05dae340d97c71acb954dba7","url":"https://api.github.com/repos/adriangmrraa/clinicforge/commits/f39c67fb087ddd4a05dae340d97c71acb954dba7"},{"autho